import React from 'react';

import { ColProps } from 'react-bootstrap';

import { AuthContext } from '@contexts/AuthContext';
import { declOfNum, formatAltitude, formatDistance } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { IWorkout } from '../@types/workouts.types';

interface IStatItemProps extends ColProps {
  children: React.ReactNode;
  label: React.ReactNode;
  small?: boolean;
}

const StatItem = ({ children, label, small, ...rest }: IStatItemProps) => {
  return (
    <PohCol xs={4} sm={small ? 3 : 4} md={small ? 2 : 3} lg={small ? 1 : 3} {...rest}>
      <h4 className="m-0">
        <strong className="text-success">{children}</strong>
      </h4>
      <small className="d-block text-muted mt-n1">{label}</small>
    </PohCol>
  );
};

interface IWorkoutsListStatisticProps {
  data: Array<IWorkout | IWorkout[]>;
}

const WorkoutsListStatistic = ({ data }: IWorkoutsListStatisticProps) => {
  const authContext = React.useContext(AuthContext);

  const myWorkouts = React.useMemo<IWorkout[]>(() => {
    if (!authContext.user?.id) return [];
    return data.map((val) =>
      Array.isArray(val) ? val.find((x) => x.user.id === authContext.user?.id) : val,
    ) as IWorkout[];
  }, [data]);
  return (
    <>
      <PohRow>
        <StatItem
          label={declOfNum(data.length, ['Занятие', 'Занятия', 'Занятий'])}
          sm={2}
          xs={6}
          md={2}
          lg={1}
        >
          {data.length}
        </StatItem>
        <StatItem label="Дистанция" sm={4} xs={6} md={3} lg={2}>
          {formatDistance(myWorkouts.reduce((acc, val) => acc + val.distance, 0))}
        </StatItem>
        <StatItem label="Набор высоты" sm={3} xs={6} md={3} lg={2}>
          {formatAltitude(myWorkouts.reduce((acc, val) => acc + val.alt_ascent, 0))}
        </StatItem>
        <StatItem label="Продолж-ть" sm={3} xs={6} md={3} lg={2}>
          {round(
            myWorkouts.reduce(
              (acc, val) => acc + (val.date_finish.getTime() - val.date_start.getTime()),
              0,
            ) / 3600000,
            1,
          )}
          &thinsp;ч
        </StatItem>
      </PohRow>
    </>
  );
};

export default WorkoutsListStatistic;
